function trailingZeroes(n) {
  let product = 1n;
  for (let i = 2n; i <= BigInt(n); i++) product *= i;
  let count = 0;
  while (product > 0n && product % 10n === 0n) {
    count += 1;
    product /= 10n;
  }
  return count;
}

