code.javascript:
function myPow(x, n) {
  let base = n < 0 ? 1 / x : x;
  let exponent = Math.abs(n);
  let result = 1;
  while (exponent > 0) {
    if (exponent % 2 === 1) result *= base;
    base *= base;
    exponent = Math.floor(exponent / 2);
  }
  return result;
}

code.python:
def my_pow(x, n):
    base = 1 / x if n < 0 else x
    exponent = abs(n)
    result = 1.0
    while exponent:
        if exponent & 1:
            result *= base
        base *= base
        exponent >>= 1
    return result

